<?php
defined('ABSPATH')||exit;
final class EduFlow_Migration_Admin {
	public function register(){foreach(array('migration_start','migration_resume','migration_resolve')as$action){add_action('admin_post_eduflow_'.$action,array($this,$action));}}
	private static function guard(){if(!current_user_can('eduflow_manage_reports')){wp_die(esc_html__('Migration Center requires migration/report administration permission.','eduflow-core'));}}
	public static function page(){self::guard();global$wpdb;$institute=EduFlow_Settings::institute_db_id();$detected=EduFlow_Migration_Service::detect();$runs=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".EduFlow_DB::table('migration_runs')." WHERE institute_id=%d ORDER BY id DESC LIMIT 50",$institute),ARRAY_A);$conflicts=$wpdb->get_results($wpdb->prepare("SELECT * FROM ".EduFlow_DB::table('migration_conflicts')." WHERE institute_id=%d ORDER BY id DESC LIMIT 50",$institute),ARRAY_A);$ready=EduFlow_Migration_Service::readiness($institute);?><div class="wrap eduflow-wrap"><h1>EduFlow Migration Center</h1><div class="notice notice-warning"><p><strong>Create a full WordPress files + database backup before production migration.</strong></p><p>Legacy plugins remain active and read-only. Running legacy and EduFlow scheduling together may cause dual-write operational behavior. Cutover never deactivates a plugin automatically.</p></div><div class="eduflow-card"><h2>Preflight &amp; Cutover Readiness: <?php echo esc_html($ready['overall']);?></h2><ul><li>EduFlow tables: <?php echo esc_html(count(EduFlow_DB::tables()));?> registered</li><li>Legacy sources: <?php echo esc_html(count($detected));?> detected/configured</li><li>Open conflicts: <?php echo esc_html($ready['conflicts_remaining']);?></li><li>Failed records: <?php echo esc_html($ready['failed_records']);?></li><li>Controlled imports completed: <?php echo esc_html($ready['completed_import_runs']);?></li><?php foreach($ready['reconciled']as$entity=>$count):?><li><?php echo esc_html(ucwords(str_replace('_',' ',$entity)));?> reconciled: <?php echo esc_html($count);?></li><?php endforeach;?><li>Google integration status is available under System Health.</li><li>Legacy plugin deactivation: Manual post-verification decision only.</li></ul></div><h2>Legacy Detection</h2><p>Only explicitly registered source schemas are importable. Unrecognized tables are reported for manual adapter mapping rather than guessed.</p><table class="widefat striped"><thead><tr><th>Source</th><th>Table</th><th>Records</th><th>Entity</th><th>Mapping</th><th>Actions</th></tr></thead><tbody><?php foreach($detected as$row):?><tr><td><?php echo esc_html($row['source_key']);?></td><td><code><?php echo esc_html($row['table']);?></code></td><td><?php echo esc_html(null===$row['record_count']?'Unknown':$row['record_count']);?></td><td><?php echo esc_html($row['entity_type']);?></td><td><?php echo esc_html($row['supported']?'Adapter registered':'Manual mapping required');?></td><td><?php if($row['supported']&&$row['detected']):self::start_form($row['source_key'],'dry_run');self::start_form($row['source_key'],'full_safe');endif;?></td></tr><?php endforeach;if(!$detected):?><tr><td colspan="6">No legacy tables or registered adapters were detected. Missing sources are safe and do not cause migration writes.</td></tr><?php endif;?></tbody></table><h2>Migration Log</h2><table class="widefat striped"><thead><tr><th>Run</th><th>Mode</th><th>Source</th><th>Cursor</th><th>Processed</th><th>Created</th><th>Linked</th><th>Skipped</th><th>Duplicates</th><th>Conflicts</th><th>Failed</th><th>Status</th><th>Started / Finished</th><th>Action</th></tr></thead><tbody><?php foreach($runs as$r):?><tr><td><?php echo esc_html($r['id']);?></td><td><?php echo esc_html($r['mode']);?></td><td><?php echo esc_html($r['source_key']);?></td><td><?php echo esc_html($r['cursor_value']);?></td><td><?php echo esc_html($r['processed']);?></td><td><?php echo esc_html($r['created_count']);?></td><td><?php echo esc_html($r['linked_count']);?></td><td><?php echo esc_html($r['skipped_count']);?></td><td><?php echo esc_html($r['duplicate_count']);?></td><td><?php echo esc_html($r['conflict_count']);?></td><td><?php echo esc_html($r['failed_count']);?></td><td><?php echo esc_html($r['run_status']);?></td><td><?php echo esc_html($r['started_at'].' / '.$r['finished_at']);?></td><td><?php if('failed'===$r['run_status']):?><a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=eduflow_migration_resume&run_id='.$r['id']),'eduflow_migration_resume_'.$r['id']));?>">Resume</a><?php endif;?></td></tr><?php endforeach;?></tbody></table><h2>Conflict Center</h2><table class="widefat striped"><thead><tr><th>ID</th><th>Run</th><th>Source record</th><th>Entity</th><th>Type</th><th>Reason</th><th>Status</th><th>Resolution</th></tr></thead><tbody><?php foreach($conflicts as$c):?><tr><td><?php echo esc_html($c['id']);?></td><td><?php echo esc_html($c['run_id']);?></td><td><?php echo esc_html($c['source_table'].' / '.$c['source_id']);?></td><td><?php echo esc_html($c['entity_type']);?></td><td><?php echo esc_html($c['conflict_type']);?></td><td><?php echo esc_html($c['reason']);?></td><td><?php echo esc_html($c['conflict_status']);?></td><td><?php if('open'===$c['conflict_status']):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_migration_resolve"><input type="hidden" name="conflict_id" value="<?php echo esc_attr($c['id']);?>"><?php wp_nonce_field('eduflow_migration_resolve_'.$c['id']);?><select name="resolution"><?php foreach(array('link_existing','create_new','skip','keep_eduflow','use_legacy','manual')as$x):?><option value="<?php echo esc_attr($x);?>"><?php echo esc_html(ucwords(str_replace('_',' ',$x)));?></option><?php endforeach;?></select><input type="number" min="0" name="target_id" placeholder="Target ID if applicable"><button class="button">Resolve</button></form><?php else:echo esc_html($c['resolution']);endif;?></td></tr><?php endforeach;?></tbody></table></div><?php }
	private static function start_form($source,$mode){?><form style="display:inline-block" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="eduflow_migration_start"><input type="hidden" name="source_key" value="<?php echo esc_attr($source);?>"><input type="hidden" name="mode" value="<?php echo esc_attr($mode);?>"><?php wp_nonce_field('eduflow_migration_start_'.$source.'_'.$mode);if('dry_run'!==$mode):?><label><input type="checkbox" name="backup_confirmed" value="1" required> Backup confirmed</label><?php endif;?><button class="button"><?php echo esc_html('dry_run'===$mode?'Run Dry Run':'Run Full Safe Import');?></button></form><?php }
	public function migration_start(){self::guard();$source=sanitize_key($_POST['source_key']??'');$mode=sanitize_key($_POST['mode']??'dry_run');check_admin_referer('eduflow_migration_start_'.$source.'_'.$mode);$result=EduFlow_Migration_Service::start($source,$mode,array(),!empty($_POST['backup_confirmed']));$this->redirect($result);}
	public function migration_resume(){self::guard();$id=absint($_GET['run_id']??0);check_admin_referer('eduflow_migration_resume_'.$id);$this->redirect(EduFlow_Migration_Service::resume($id));}
	public function migration_resolve(){self::guard();$id=absint($_POST['conflict_id']??0);check_admin_referer('eduflow_migration_resolve_'.$id);$this->redirect(EduFlow_Migration_Service::resolve($id,sanitize_key($_POST['resolution']??''),absint($_POST['target_id']??0)));}
	private function redirect($result){$message=is_wp_error($result)?$result->get_error_message():'Migration action queued.';wp_safe_redirect(add_query_arg(array('page'=>'eduflow-migration','eduflow_notice'=>rawurlencode($message)),admin_url('admin.php')));exit;}
}
